from collections import defaultdict
import json
import logging
import re
from robot.utils.robottypes import is_truthy

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


def _normalize(process_name):
    return re.sub(r"[^a-zA-Z]*", "", process_name).upper()


def _first_key(dct):
    return list(dct.keys())[0]


class GetResourcesUsage(object):

    _get_resource_usage_template = "getResourcesUsage{options}{process_node_suffix}"

    def get_resources_usage(self, name, detailed=True, ignore_json_decoding_error=True):
        """
        Return resource usage from 5G and 4G C-plane components.

        :param str name: AaShell CLI alias name
        :param bool detailed: (optional) provides detailed output format (option -l for 5g and -a for 4g), it should be
                              given False if short output format (default option for 5g and -n for 4g), default value
                              is True
        :param bool ignore_json_decoding_error: (optional) unexpected aashell response having 'No response received from
                                                some component(s)!' error message causing json decode error can be
                                                ignored by providing this flag as True

        :rtype: dict
        :return:
            resource usage parameters for 5G example::

                {
                    'CPIF': {
                        'cpUeAppIdList':[
                            {
                                'cpUeAppId': 18,
                                'numOfNonGbrBearers': 0,
                                'numOfUsers': 0
                            }
                        ],
                        'ueMapping': {
                            'ueMappingTable': []
                        }
                    }
                    ....
                }

            resource usage parameters for 4G example::

                {
                    'UEC':  [
                        {
                            'contextInfoList': [],
                            'numBearers': '0',
                            'numBearersPreempt': '0',
                            'numCells': '0',
                            'numContexts': '0',
                            'transactionId': '0'},
                        {
                            'contextInfoList': [],
                            'numBearers': '0',
                            'numBearersPreempt': '0',
                            'numCells': '0',
                            'numContexts': '0',
                            'transactionId': '1'}
                    ]
                    ...
                }
        """
        all_resources = {}
        for process_node_suffix in self._extract_process_node_suffixes(name, command='getResourcesUsage'):
            self._assert_command_available_in_help(name,
                                                   "help{process_node_suffix}".format(
                                                       process_node_suffix=process_node_suffix),
                                                   "getResourcesUsage")
            get_resource_usage_command = self._get_resource_usage_template.format(
                options=self._get_applicable_option(name, process_node_suffix, is_truthy(detailed)),
                process_node_suffix=process_node_suffix)
            get_resource_usage_output = self.execute_aashell_command(
                name=name,
                command=get_resource_usage_command)
            try:
                resources = self._decode_json_data(get_resource_usage_output, ignore_json_decoding_error)
            except ValueError:
                error_message = "Json decoding failed.\n" \
                                "Please check for any unexpected error message in '{command}' output\n" \
                                "Example:'No response received from some component(s)!'\n" \
                                "'{command}' output: {output}".format(
                                    command=get_resource_usage_command,
                                    output=get_resource_usage_output)
                raise ValueError(error_message)
            for key in list(resources.keys()):
                all_resources.update(
                    self._expand_group_response(resources, key))
            if resources:
                process = self._get_process_name(name, process_node_suffix)
                all_resources[_normalize(process)] = resources
        return all_resources

    @staticmethod
    def _decode_json_data(get_resource_usage_output, ignore_json_decoding_error):
        try:
            resources = json.loads(get_resource_usage_output)
        except ValueError as error:
            if ignore_json_decoding_error:
                logger.warn('Attempting to handle "[!]: No response received from some component(s)!" error')
                resources = json.loads(
                    get_resource_usage_output[:get_resource_usage_output.index(u"\n\n")])
            else:
                raise error
        return resources

    def _get_applicable_option(self, name, process_node_suffix, detailed):
        if "-l --long" in self.execute_aashell_command(
                name=name,
                command=self._get_resource_usage_template.format(
                    options=' -h',
                    process_node_suffix=process_node_suffix)):
            return ' -l' if detailed else ''
        else:
            return ' -a -j' if detailed else ' -n -j'

    @staticmethod
    def _expand_group_response(resources, key):
        extracted_resources = defaultdict(list)
        match = re.match(r"(.*)GetResourceUsageResp", key)
        if match:
            extracted_resources[_normalize(match.group(1))] = resources[key]
            del resources[key]
        elif key == "ResourcesUsageInfoResponses":
            for element in sorted(resources[key], key=_first_key):
                component_key = _first_key(element)
                component_name = component_key.split()[0]
                component_value = element[component_key]
                extracted_resources[component_name].append(component_value)
            del resources[key]
        return extracted_resources

    def _get_process_name(self, name, process_node_suffix):
        return re.findall(
            r"getResourcesUsage        (?:Displays resources usage on|Display output of getResourcesUsage on) (\S+)",
            self.execute_aashell_command(
                name=name,
                command="help{process_node_suffix}".format(
                    process_node_suffix=process_node_suffix)),
            re.DOTALL)[-1]
